insert into product_faqs (id, product_code, question, answer, source) values
  ('A-AS001-1', 'A-AS001', 'Apa saja isi dalam kardus?', 'Satu kompor batik listrik ASTOETIK versi Standar, satu wajan khusus batik, kartu garansi, dan buku petunjuk penggunaan.', 'manual'),
  ('A-AS001-2', 'A-AS001', 'Bagaimana cara menyalakan kompor?', 'Letakkan wajan di atas tungku, masukkan potongan malam, pastikan skala pemanas di titik terendah, colokkan steker, lalu putar skala pemanas searah jarum jam sampai lampu indikator merah menyala.', 'manual'),
  ('A-AS001-3', 'A-AS001', 'Berapa banyak malam yang boleh dimasukkan?', 'Masukkan malam yang sudah dipotong-potong sesuai kebutuhan, dengan berat maksimal sekitar 250 gram pada wajan batik.', 'manual'),
  ('A-AS001-4', 'A-AS001', 'Bagaimana mengatur suhu malam?', 'Putar skala pemanas (potensio) searah jarum jam untuk menaikkan suhu dan berlawanan arah jarum jam untuk menurunkan. Malam siap dicantingkan bila sudah mencair rata.', 'manual'),
  ('A-AS001-5', 'A-AS001', 'Bagaimana cara mematikan kompor dengan aman?', 'Putar skala pemanas ke titik terendah, lalu cabut steker dari stop kontak. Tunggu minimal 15 detik sebelum menyalakan kembali.', 'manual'),
  ('A-AS001-6', 'A-AS001', 'Lampu indikator tidak menyala, apa yang harus dilakukan?', 'Pastikan steker sudah terhubung ke stop kontak dan arus listrik normal. Jika masih bermasalah, hubungi technical support Astoetik.', 'manual'),
  ('A-AS001-7', 'A-AS001', 'Bagaimana membersihkan bodi yang terkena malam?', 'Lap bodi dengan air panas atau minyak tanah saat kompor dalam kondisi mati dan steker sudah dicabut. Jauhkan kompor dari air atau hujan.', 'manual'),
  ('A-AS002-1', 'A-AS002', 'Berapa daya dan tegangan produk ini?', 'Menurut data produk, Kompor Batik Listrik v1 memiliki daya 150 W. Pastikan instalasi listrik di rumah sesuai sebelum digunakan.', 'generated'),
  ('A-AS002-2', 'A-AS002', 'Apa bahan bodi produk ini?', 'Bahan bodi Kompor Batik Listrik v1 adalah Alumunium.', 'generated'),
  ('A-AS002-3', 'A-AS002', 'Apakah produk ini bersertifikat SNI atau TKDN?', 'Data SNI/TKDN untuk produk ini belum tercantum. Silakan tanyakan ke CS melalui WhatsApp.', 'generated'),
  ('A-AS002-4', 'A-AS002', 'Apa tips aman menggunakan alat batik listrik?', 'Gunakan di permukaan datar dan kering, jauhkan dari air dan jangkauan anak-anak, jangan menyentuh bagian panas saat menyala, dan cabut steker setelah selesai atau bila tidak dipakai lama.', 'generated'),
  ('A-AS002-5', 'A-AS002', 'Bagaimana menanyakan stok, garansi, atau cara pembelian?', 'Untuk stok, garansi, dan pembelian, silakan hubungi CS Astoetik melalui tombol WhatsApp di halaman ini atau beli lewat marketplace.', 'generated'),
  ('A-AS003-1', 'A-AS003', 'Berapa daya dan tegangan produk ini?', 'Menurut data produk, Kompor Batik Tulis Listrik memiliki daya 150 W. Pastikan instalasi listrik di rumah sesuai sebelum digunakan.', 'generated'),
  ('A-AS003-2', 'A-AS003', 'Apa bahan bodi produk ini?', 'Bahan bodi Kompor Batik Tulis Listrik adalah Kayu.', 'generated'),
